//! Header anchors: known block hashes that authenticate a header chain without
//! recomputing its KAWPOW proof of work.
//!
//! The mainnet list is Neurai core's `src/chainparamsanchors.h` (commit b778146,
//! "Speed up initial header sync"): generated by `contrib/devtools/gen-header-anchors.py`
//! and independently verified (provenance in `contrib/devtools/header-anchors/2026-10-08`).
//! One hash every 2,000 blocks through height 1,732,000. Neurai core uses it the same way
//! during header sync; all of them match the chain of a v1.0.7 node.
//!
//! Why it is sound: the KAWPOW block hash commits to every header field, `prev_blockhash`
//! and `mix_hash` included. A header whose hash equals an anchor is that block's header,
//! and so is every header it links back to through `prev_blockhash`.

use bitcoin::BlockHash;
use std::str::FromStr;

mod mainnet;
pub use mainnet::MAINNET;

/// Blocks between anchors: `anchors[i]` is the hash of block `(i + 1) * INTERVAL`.
pub const INTERVAL: usize = 2000;

/// How to treat a batch of contiguous headers, given the network's anchors.
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct AnchoredBatch {
    /// Accept `headers[..keep]`. The rest is requested again, so that the next batch
    /// starts at this anchor and ends at the next one.
    pub keep: usize,
    /// `headers[verify_from..keep]` are not covered by an anchor: verify their KAWPOW.
    pub verify_from: usize,
    /// An anchor height in the batch whose hash is not the anchor (another chain):
    /// nothing is skipped then.
    pub mismatch: Option<usize>,
}

fn anchor(anchors: &[&str], height: usize) -> Option<BlockHash> {
    if height == 0 || height % INTERVAL != 0 {
        return None;
    }
    let hex = anchors.get(height / INTERVAL - 1)?;
    Some(BlockHash::from_str(hex).expect("invalid anchor hash"))
}

/// `batch` holds the `(hash, height)` of contiguous headers, each one linking to the
/// previous one through `prev_blockhash` (the caller checks that).
pub(crate) fn split_batch(anchors: &[&str], batch: &[(BlockHash, usize)]) -> AnchoredBatch {
    let mut mismatch = None;
    let mut anchored = None;
    for (i, &(hash, height)) in batch.iter().enumerate() {
        match anchor(anchors, height) {
            Some(a) if a == hash => anchored = Some(i),
            Some(_) => mismatch = mismatch.or(Some(height)),
            None => (),
        }
    }
    let all = batch.len();
    match (anchored, mismatch) {
        (Some(i), None) => {
            let next_anchor = anchor(anchors, batch[i].1 + INTERVAL).is_some();
            if i + 1 < all && next_anchor {
                AnchoredBatch {
                    keep: i + 1,
                    verify_from: i + 1,
                    mismatch,
                }
            } else {
                AnchoredBatch {
                    keep: all,
                    verify_from: i + 1,
                    mismatch,
                }
            }
        }
        _ => AnchoredBatch {
            keep: all,
            verify_from: 0,
            mismatch,
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use bitcoin::hashes::{sha256d, Hash};

    fn hash(n: usize) -> BlockHash {
        let mut b = [0u8; 32];
        b[..8].copy_from_slice(&(n as u64).to_le_bytes());
        BlockHash::from_raw_hash(sha256d::Hash::from_byte_array(b))
    }

    /// Heights `from..=to`, hashed by height (so they match `anchors()`), except `fork`.
    fn batch(from: usize, to: usize, fork: Option<usize>) -> Vec<(BlockHash, usize)> {
        (from..=to)
            .map(|h| {
                (
                    if Some(h) == fork {
                        hash(h + 1_000_000)
                    } else {
                        hash(h)
                    },
                    h,
                )
            })
            .collect()
    }

    fn with_anchors<R>(f: impl FnOnce(&[&str]) -> R) -> R {
        let owned: Vec<String> = [2000, 4000, 6000]
            .iter()
            .map(|&h| hash(h).to_string())
            .collect();
        let anchors: Vec<&str> = owned.iter().map(String::as_str).collect();
        f(&anchors)
    }

    #[test]
    fn mainnet_anchors_parse() {
        assert_eq!(MAINNET.len(), 866);
        assert_eq!(MAINNET.len() * INTERVAL, 1_732_000);
        for height in (INTERVAL..=MAINNET.len() * INTERVAL).step_by(INTERVAL) {
            assert!(anchor(MAINNET, height).is_some());
        }
        assert_eq!(
            anchor(MAINNET, 2000).unwrap().to_string(),
            "000000069dc1a6be3f49d5bdffd1209290d731cceacdb6646119165ba332f8f6"
        );
        assert_eq!(anchor(MAINNET, 1_734_000), None);
        assert_eq!(anchor(MAINNET, 2001), None);
        assert_eq!(anchor(MAINNET, 0), None);
    }

    #[test]
    fn batch_ending_at_an_anchor_needs_no_verification() {
        with_anchors(|a| {
            let b = batch(1, 2000, None);
            assert_eq!(
                split_batch(a, &b),
                AnchoredBatch {
                    keep: 2000,
                    verify_from: 2000,
                    mismatch: None
                }
            );
        })
    }

    #[test]
    fn batch_past_an_anchor_is_cut_at_it() {
        with_anchors(|a| {
            // heights 1001..=3000: keep 1001..=2000, the next batch is 2001..=4000
            let b = batch(1001, 3000, None);
            assert_eq!(
                split_batch(a, &b),
                AnchoredBatch {
                    keep: 1000,
                    verify_from: 1000,
                    mismatch: None
                }
            );
        })
    }

    #[test]
    fn headers_after_the_last_anchor_are_verified() {
        with_anchors(|a| {
            // 6000 is the last anchor: keep everything, verify 6001..=6500
            let b = batch(5001, 6500, None);
            assert_eq!(
                split_batch(a, &b),
                AnchoredBatch {
                    keep: 1500,
                    verify_from: 1000,
                    mismatch: None
                }
            );
            let b = batch(6001, 6100, None);
            assert_eq!(
                split_batch(a, &b),
                AnchoredBatch {
                    keep: 100,
                    verify_from: 0,
                    mismatch: None
                }
            );
        })
    }

    #[test]
    fn batch_without_an_anchor_is_verified() {
        with_anchors(|a| {
            let b = batch(2001, 2100, None);
            assert_eq!(
                split_batch(a, &b),
                AnchoredBatch {
                    keep: 100,
                    verify_from: 0,
                    mismatch: None
                }
            );
        });
        // testnet and regtest have no anchors
        let b = batch(1, 2000, None);
        assert_eq!(
            split_batch(&[], &b),
            AnchoredBatch {
                keep: 2000,
                verify_from: 0,
                mismatch: None
            }
        );
    }

    #[test]
    fn anchor_mismatch_verifies_everything() {
        with_anchors(|a| {
            let b = batch(1001, 3000, Some(2000));
            assert_eq!(
                split_batch(a, &b),
                AnchoredBatch {
                    keep: 2000,
                    verify_from: 0,
                    mismatch: Some(2000)
                }
            );
        })
    }
}
